--[[
    Vxz Script v6 | WindUI Custom Background Edition
    Background: embedded from the supplied anime image.
]]

local VXZ_BACKGROUND_BASE64 = [[]]
local VXZ_BACKGROUND_FILE = "Vxz_Custom_Background.jpg"

local function VXZBase64Decode(data)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    data = tostring(data or ""):gsub("[^" .. alphabet .. "=]", "")

    local lookup = {}
    for i = 1, #alphabet do
        lookup[alphabet:sub(i, i)] = i - 1
    end

    local output = {}
    local buffer = 0
    local bits = 0

    for i = 1, #data do
        local c = data:sub(i, i)
        if c ~= "=" then
            local value = lookup[c]
            if value then
                buffer = buffer * 64 + value
                bits = bits + 6

                while bits >= 8 do
                    bits = bits - 8
                    local byte = math.floor(buffer / (2 ^ bits)) % 256
                    output[#output + 1] = string.char(byte)
                    buffer = buffer % (2 ^ bits)
                end
            end
        end
    end

    return table.concat(output)
end

local function GetVxzEmbeddedBackground()
    local fallback = "rbxassetid://96507801672361"

    local assetFunction = getcustomasset or getsynasset
    if type(assetFunction) ~= "function" or type(writefile) ~= "function" then
        return fallback
    end

    local ok, result = pcall(function()
        local exists = type(isfile) == "function" and isfile(VXZ_BACKGROUND_FILE)
        if not exists then
            writefile(VXZ_BACKGROUND_FILE, VXZBase64Decode(VXZ_BACKGROUND_BASE64))
        end
        return assetFunction(VXZ_BACKGROUND_FILE)
    end)

    if ok and result then
        return result
    end

    return fallback
end

local VXZ_BACKGROUND = GetVxzEmbeddedBackground()

