local function GetAdaptiveSpeed()
local boost = math.clamp(tonumber(Config.BoostLevel) or Config.MinBoost, Config.MinBoost, Config.MaxBoost)
return Config.BaseWalkSpeed + (boost * 40)
end

local function GetESPAdornee(object)
if not object then return nil end
if object:IsA("BasePart") then return object end
if object:IsA("Model") then
local primary = object.PrimaryPart
if primary and primary:IsA("BasePart") then return primary end
local root = object:FindFirstChildWhichIsA("BasePart", true)
return root
end
return nil
end

local function StartPlayerAura()
DisconnectConnection("PlayerAuraLoop")
Connections.PlayerAuraLoop = RunService.RenderStepped:Connect(function()
if not Config.PlayerAuraEnabled then return end
for _, player in ipairs(Players:GetPlayers()) do
if player ~= LocalPlayer and player.Character then
local root = GetRoot(player.Character)
if root then
if not OriginalPlayerSizes[root] then
OriginalPlayerSizes[root] = {
Size = root.Size,
Transparency = root.Transparency,
Color = root.Color,
Material = root.Material,
CanCollide = root.CanCollide
}
end
pcall(function()
root.Size = Vector3.new(Config.PlayerAuraSize, Config.PlayerAuraSize, Config.PlayerAuraSize)
root.Transparency = 0.9
root.Color = Color3.fromRGB(255, 255, 255)
root.Material = Enum.Material.ForceField
root.CanCollide = false
end)
end
end
end
end)
end

local function StopPlayerAura()
DisconnectConnection("PlayerAuraLoop")
for root, data in pairs(OriginalPlayerSizes) do
if root and root.Parent then
pcall(function()
root.Size = data.Size
root.Transparency = data.Transparency
root.Color = data.Color
root.Material = data.Material
root.CanCollide = data.CanCollide
end)
end
end
table.clear(OriginalPlayerSizes)
end

