local function GetGuardInfo(object)
local guardName = object.Name
local zoneName = "Unknown Zone"
local color = Color3.fromRGB(255, 165, 0)

local current = object.Parent  
while current and current ~= Workspace do  
    local cName = current.Name  
    local lowerCName = cName:lower()  
    if lowerCName:find("zone") or lowerCName:find("area") or lowerCName:find("map") or lowerCName:find("spawn") or lowerCName:find("base") then  
        zoneName = cName  
        break  
    end  
    current = current.Parent  
end  

local combined = (guardName .. " " .. zoneName):lower()  
if combined:find("zone1") or combined:find("khu 1") or combined:find("easy") then  
    color = Color3.fromRGB(0, 255, 255)  
elseif combined:find("zone2") or combined:find("khu 2") or combined:find("medium") then  
    color = Color3.fromRGB(0, 255, 0)  
elseif combined:find("zone3") or combined:find("khu 3") or combined:find("hard") then  
    color = Color3.fromRGB(255, 255, 0)  
elseif combined:find("zone4") or combined:find("khu 4") or combined:find("extreme") then  
    color = Color3.fromRGB(255, 128, 0)  
elseif combined:find("boss") or combined:find("vip") then  
    color = Color3.fromRGB(255, 0, 255)  
else  
    local hash = 0  
    for i = 1, #guardName do  
        hash = hash + string.byte(guardName, i)  
    end  
    local r = (hash * 37) % 200 + 55  
    local g = (hash * 47) % 200 + 55  
    local b = (hash * 57) % 200 + 55  
    color = Color3.fromRGB(r, g, b)  
end  

return guardName, zoneName, color

end

